bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
compose=(docker compose -p deploy -f deploy/gserver-compose.yaml)
test "$(docker inspect -f '{{.State.Running}}' deploy-gaybbs-1)" = true
test "$(docker exec deploy-gaybbs-1 sha256sum /app/gaybbs.mjs | cut -d' ' -f1)" = 22c930f364bcec223a0a3ddca9d04dbadf74d1bc4cffe4d08494ef8e1a4311b7
pg_before="$(docker inspect -f '{{.Id}}' deploy-postgres-1)"
ub_before="$(systemctl --user show -p MainPID --value gace-userbot-verify.service)"
restore(){ "${compose[@]}" up -d --no-deps --no-build gaybbs >/dev/null; }
trap restore EXIT
"${compose[@]}" stop -t 15 gaybbs >/dev/null
test "$(docker inspect -f '{{.State.Running}}' deploy-gaybbs-1)" = false
"${compose[@]}" run --rm -T --no-deps --entrypoint node gaybbs --import /app/preload/telegram-ipv4-preload.mjs --input-type=module <<'JS'
import fs from 'node:fs';
import https from 'node:https';
const token=fs.readFileSync(process.env.BOT_TOKEN_FILE,'utf8').trim();
async function call(method,payload){
 return new Promise(resolve=>{
  const body=JSON.stringify(payload);
  const req=https.request('https://api.telegram.org/bot'+token+'/'+method,{method:'POST',family:4,timeout:12000,headers:{'content-type':'application/json','content-length':Buffer.byteLength(body)}},res=>{
   let s='';res.on('data',c=>s+=c);res.on('end',()=>{try{const j=JSON.parse(s);resolve({http:res.statusCode,ok:j.ok===true,result:j.result});}catch{resolve({http:res.statusCode,ok:false});}});
  });req.on('timeout',()=>req.destroy());req.on('error',e=>resolve({ok:false,error:e.code||'NETWORK_ERROR'}));req.end(body);
 });
}
const a=await call('getWebhookInfo',{});
console.log('QUEUE_BEFORE',JSON.stringify({ok:a.ok,pending:a.result?.pending_update_count,webhook:!!a.result?.url}));
if(!a.ok||a.result?.url)process.exit(2);
// No offset, no negative offset, no drop_pending_updates, no payload output.
// Observe one pending item without acknowledging it.
const b=await call('getUpdates',{limit:1,timeout:0});
console.log('SINGLE_OWNER_UPDATE_PROBE',JSON.stringify({ok:b.ok,http:b.http,error:b.error,count:Array.isArray(b.result)?b.result.length:null,kind:Array.isArray(b.result)&&b.result.length?Object.keys(b.result[0]).filter(k=>k!=='update_id'):[]}));
const c=await call('getWebhookInfo',{});
console.log('QUEUE_AFTER_NONACK_PROBE',JSON.stringify({ok:c.ok,pending:c.result?.pending_update_count}));
JS
restore
trap - EXIT
test "$(docker inspect -f '{{.Id}}' deploy-postgres-1)" = "$pg_before"
test "$(systemctl --user show -p MainPID --value gace-userbot-verify.service)" = "$ub_before"
echo DB_AND_USERBOT_UNCHANGED=PASS
